$ErrorActionPreference='Stop';$root='C:\Users\gjpat\.codex\visualizations\2026\07\25\019f9725-e843-78c3-840c-539c3894ce28';$src=Join-Path $root 'checkin-police-12-slide-launch-v2.pptx';$audio=Join-Path $root 'police-12-marathi-audio';$out=Join-Path $root 'checkin-police-12-slide-launch-marathi.mp4';$pptx=Join-Path $root 'checkin-police-12-slide-launch-marathi.pptx';$timings=Get-Content -Raw (Join-Path $audio 'timings.json')|ConvertFrom-Json
$app=New-Object -ComObject PowerPoint.Application;$app.Visible=-1;$deck=$null
try{$deck=$app.Presentations.Open($src,$false,$false,$false);for($i=1;$i -le $deck.Slides.Count;$i++){$s=$deck.Slides.Item($i);$f=Join-Path $audio ('slide-{0:00}.mp3' -f $i);$a=$s.Shapes.AddMediaObject2($f,$false,$true,0,0,1,1);$a.AnimationSettings.PlaySettings.PlayOnEntry=$true;$a.AnimationSettings.PlaySettings.HideWhileNotPlaying=$true;$s.SlideShowTransition.AdvanceOnTime=$true;$s.SlideShowTransition.AdvanceTime=[double]$timings[$i-1].seconds+0.8};if(Test-Path $pptx){Remove-Item $pptx -Force};if(Test-Path $out){Remove-Item $out -Force};$deck.SaveAs($pptx);$deck.CreateVideo($out,$true,5,1920,30,85);Start-Sleep 20;$d=(Get-Date).AddMinutes(12);$last=-1;$stable=0;while((Get-Date)-lt $d){$len=if(Test-Path $out){(Get-Item $out).Length}else{0};if($len -gt 1MB -and $len -eq $last){$stable++}else{$stable=0};if($stable -ge 3){break};$last=$len;Start-Sleep 10};Get-Item $out|Select-Object FullName,Length}finally{if($deck){try{$deck.Close()}catch{}};$app.Quit()}
